mod sparse;mod scheduler;
#[cfg(test)]mod tests{
 use super::{scheduler::{*,search::*},sparse::{Owner,Charge,Polynomial}};use std::time::{Instant,Duration};
 #[derive(Default)]struct Ledger{work:u64,bytes:u64,checks:u64,stop:Option<u64>}
 impl Owner for Ledger{fn reserve(&mut self,q:Charge)->Result<(),()>{self.work+=q.work;self.bytes+=q.bytes;Ok(())}fn check(&mut self)->Result<(),()>{self.checks+=1;if self.stop.is_some_and(|s|self.checks>=s){Err(())}else{Ok(())}}}
 fn limits()->SearchLimits{SearchLimits{nodes:32,native:Limits{batch_rows:128,batch_ops:1024,batches:32,variables:256,generators:64,basis:64,tasks:1024,terms:256,proof:1024,degree:256,work:20_000_000,bytes:200_000_000}}}
 fn valid(g:&[Polynomial],x:&[bool])->bool{g.iter().all(|p|!p.iter().fold(false,|s,t|s^t.iter().all(|v|x[*v as usize])))}
 fn identity(g:&[Polynomial],r:&Row)->bool{let mut out=std::collections::BTreeSet::new();for t in &r.proof{if t.generator>=g.len(){return false}for m in &g[t.generator]{let mut u=m.clone();u.extend(&t.multiplier);u.sort();u.dedup();if !out.insert(u.clone()){out.remove(&u);}}}out==r.polynomial.iter().cloned().collect()}
 fn check(g:&[Polynomial],a:&SearchAttempt){for (i,n)in a.nodes.iter().enumerate(){assert_eq!(n.equations.len(),n.origins.len());if let Some(native)=&n.native{for r in &native.basis{assert!(identity(&n.equations,r));}for b in &native.batches{for r in b.initial.iter().chain(&b.matrix).chain(&b.staged_basis){assert!(identity(&n.equations,r));}}}for(p,o)in n.equations.iter().zip(&n.origins){match o{Origin::Original(j)=>assert_eq!(p,&g[*j]),Origin::Branch{parent,variable,value}=>{assert!(*parent<i);assert!(a.nodes[*parent].children[*value as usize].is_some());let expected=if *value{vec![vec![],vec![*variable]]}else{vec![vec![*variable]]};assert_eq!(p,&expected);}}}if n.status==NodeStatus::Branched{assert!(n.children.iter().all(Option::is_some));}if n.status==NodeStatus::Refuted{let r=&n.native.as_ref().unwrap().basis[n.refutation_row.unwrap()];assert_eq!(r.polynomial,vec![Vec::<u32>::new()]);}}if let Some(i)=a.witness_node{assert!(valid(g,&a.nodes[i].candidate));assert!(valid(&a.nodes[i].equations,&a.nodes[i].candidate));assert_eq!(a.verdict,Verdict::Witness);assert!(!a.queue.contains(&i));}}
 #[test]fn satisfiable_requires_actual_branch_and_retains_both_children(){let g=vec![vec![vec![],vec![0],vec![1]]];let mut l=Ledger::default();let a=solve(2,&g,limits(),Instant::now()+Duration::from_secs(5),&mut l);check(&g,&a);assert_eq!(a.result,Ok(()));assert_eq!(a.verdict,Verdict::Witness);assert_eq!(a.nodes[0].status,NodeStatus::Branched);assert!(a.nodes.len()>=3);assert!(a.nodes.iter().filter(|n|n.native.is_some()).count()>=2);assert_eq!(a.charge.work,l.work);assert_eq!(a.charge.bytes,l.bytes);}
 #[test]fn unsat_has_retained_original_row_derivation(){let g=vec![vec![vec![0]],vec![vec![],vec![0]]];let a=solve(1,&g,limits(),Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.result,Ok(()));assert_eq!(a.verdict,Verdict::UnsatDerived);assert!(a.queue.is_empty());}
 #[test]fn above128_model_and_partial_node_limit(){let g=vec![vec![vec![],vec![129]]];let a=solve(130,&g,limits(),Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.verdict,Verdict::Witness);assert!(a.nodes[a.witness_node.unwrap()].candidate[129]);let mut l=limits();l.nodes=1;let g=vec![vec![vec![],vec![0],vec![1]]];let a=solve(2,&g,l,Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.result,Err(Failure::Cap));assert_eq!(a.verdict,Verdict::Unknown);assert_eq!(a.nodes[0].candidate_valid,Some(false));assert_eq!(a.queue,vec![0]);}
 #[test]fn owner_sweep_preserves_branch_origins_and_single_cumulative_charge(){let g=vec![vec![vec![],vec![0],vec![1]]];let mut base=Ledger::default();let full=solve(2,&g,limits(),Instant::now()+Duration::from_secs(5),&mut base);assert_eq!(full.verdict,Verdict::Witness);let mut stopped_child=false;for at in 1..=base.checks{let mut o=Ledger{stop:Some(at),..Default::default()};let a=solve(2,&g,limits(),Instant::now()+Duration::from_secs(5),&mut o);check(&g,&a);assert_eq!(a.result,Err(Failure::Owner));assert_eq!(a.verdict,Verdict::Unknown);assert_eq!(a.charge.work,o.work);assert_eq!(a.charge.bytes,o.bytes);stopped_child|=a.nodes.len()>1;}assert!(stopped_child);}
 #[test]fn both_children_execute_with_conditional_refutation(){let g=vec![vec![vec![],vec![0]],vec![vec![],vec![1],vec![2]]];let a=solve(3,&g,limits(),Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.result,Ok(()));assert_eq!(a.verdict,Verdict::Witness);let f=a.nodes[0].children[0].unwrap();let t=a.nodes[0].children[1].unwrap();assert_eq!(a.nodes[f].status,NodeStatus::Refuted);assert!(a.nodes[t].native.is_some());let r=&a.nodes[f].native.as_ref().unwrap().basis[a.nodes[f].refutation_row.unwrap()];assert!(r.proof.iter().any(|p|matches!(a.nodes[f].origins[p.generator],Origin::Branch{value:false,..})));}
 #[test]fn deadline_and_small_global_work_budget_stop_without_reset(){let g=vec![vec![vec![],vec![0],vec![1]]];let a=solve(2,&g,limits(),Instant::now(),&mut Ledger::default());assert_eq!(a.result,Err(Failure::Deadline));for cap in [0,1,10,100,1000]{let mut l=limits();l.native.work=cap;let mut o=Ledger::default();let a=solve(2,&g,l,Instant::now()+Duration::from_secs(5),&mut o);check(&g,&a);assert_eq!(a.verdict,Verdict::Unknown);assert!(a.charge.work<=cap);assert_eq!(a.charge.work,o.work);}}

 #[test]fn local_batch_cap_uses_committed_unit_for_exact_model(){let g=vec![vec![vec![],vec![0]]];let mut l=limits();l.native.batches=1;let a=solve(1,&g,l,Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.result,Ok(()));assert_eq!(a.verdict,Verdict::Witness);let node=&a.nodes[0];assert_eq!(node.native_disposition,Some(NativeDisposition::LocalCap));assert_eq!(node.native.as_ref().unwrap().result,Err(Failure::Cap));assert!(!node.native.as_ref().unwrap().complete);assert_eq!(node.candidate,vec![true]);}
 #[test]fn local_degree_cap_continues_real_branch_search(){let g=vec![vec![vec![],vec![0,1]]];let mut l=limits();l.native.degree=2;let a=solve(2,&g,l,Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.result,Ok(()));assert_eq!(a.verdict,Verdict::Witness);assert_eq!(a.nodes[0].native_disposition,Some(NativeDisposition::LocalCap));assert_eq!(a.nodes[0].status,NodeStatus::Branched);assert!(a.nodes[0].children.iter().all(Option::is_some));assert!(a.nodes.iter().filter(|n|n.native.is_some()).count()>=2);}
 #[test]fn local_batch_cap_preserves_committed_one_refutation(){let g=vec![vec![vec![0]],vec![vec![],vec![0]]];let mut l=limits();l.native.batches=1;let a=solve(1,&g,l,Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.result,Ok(()));assert_eq!(a.verdict,Verdict::UnsatDerived);assert_eq!(a.nodes[0].native_disposition,Some(NativeDisposition::LocalCap));assert_eq!(a.nodes[0].native.as_ref().unwrap().result,Err(Failure::Cap));assert_eq!(a.nodes[0].status,NodeStatus::Refuted);}
 #[test]fn parent_stop_never_becomes_local_cap_continuation(){let g=vec![vec![vec![],vec![0],vec![1]]];let mut l=limits();l.native.batches=1;let mut base=Ledger::default();let full=solve(2,&g,l,Instant::now()+Duration::from_secs(5),&mut base);assert_eq!(full.verdict,Verdict::Witness);let mut saw_native_stop=false;for at in 1..=base.checks{let mut o=Ledger{stop:Some(at),..Default::default()};let a=solve(2,&g,l,Instant::now()+Duration::from_secs(5),&mut o);check(&g,&a);assert_eq!(a.result,Err(Failure::Owner));assert_eq!(a.verdict,Verdict::Unknown);assert_eq!(a.charge.work,o.work);for n in &a.nodes{if n.native_disposition==Some(NativeDisposition::Stopped){saw_native_stop=true;assert!(n.candidate.is_empty());assert!(n.children.iter().all(Option::is_none));}}}assert!(saw_native_stop);}

 #[test]fn cap_without_committed_leaf_refutation_stays_unknown(){let g=vec![vec![vec![],vec![0],vec![1]]];let mut l=limits();l.native.degree=1;let a=solve(2,&g,l,Instant::now()+Duration::from_secs(5),&mut Ledger::default());check(&g,&a);assert_eq!(a.result,Err(Failure::Cap));assert_eq!(a.verdict,Verdict::Unknown);assert!(a.nodes.iter().any(|n|n.native_disposition==Some(NativeDisposition::LocalCap)));assert!(a.nodes.iter().all(|n|n.status!=NodeStatus::Refuted));}

}
